/**
 * Production VectorIndexProvider backed by PostgreSQL/pgvector.
 *
 * Uses cosine similarity search over the issue_embeddings table.
 * Embeddings are generated by the EmbeddingProvider and stored with
 * model version and text hash for drift detection.
 *
 * Key invariants:
 * - Embedding is bound to issue revision (textHash) and model version.
 * - Stale embeddings (textHash mismatch) are flagged but still returned
 *   in search results with a note in health.
 * - Model version changes trigger re-indexing via the reindex command.
 * - If pgvector extension is not installed, the provider reports degraded health.
 */

import type { VectorIndexProvider, VectorDocument, SemanticMatch, SemanticIndexHealth } from "./semantic-index";
import type { EmbeddingProvider } from "./embedding-provider";
import { createHash } from "node:crypto";

export interface PgVectorIndexProviderConfig {
  /** Minimum similarity threshold (cosine) for search results. */
  minSimilarity?: number;
  /** Maximum number of stale documents before health reports "degraded". */
  staleThreshold?: number;
}

/**
 * Minimal interface for Prisma raw query execution — avoids coupling to the
 * full PrismaService type while remaining testable.
 */
export interface PgVectorQueryExecutor {
  $queryRawUnsafe<T = unknown>(query: string, ...values: unknown[]): Promise<T>;
  $executeRawUnsafe(query: string, ...values: unknown[]): Promise<number>;
}

/**
 * Production pgvector-backed semantic index provider.
 */
export class PgVectorIndexProvider implements VectorIndexProvider {
  private readonly minSimilarity: number;
  private readonly staleThreshold: number;

  constructor(
    private readonly db: PgVectorQueryExecutor,
    private readonly embeddingProvider: EmbeddingProvider,
    config?: PgVectorIndexProviderConfig,
  ) {
    this.minSimilarity = config?.minSimilarity ?? 0.3;
    this.staleThreshold = config?.staleThreshold ?? 100;
  }

  async upsert(doc: VectorDocument): Promise<void> {
    const textHash = computeTextHash(doc.text);
    const embeddingResult = await this.embeddingProvider.embed(doc.text);

    const embeddingArray = `[${embeddingResult.embedding.join(",")}]`;

    await this.db.$executeRawUnsafe(
      `INSERT INTO issue_embeddings ("id", "issueNumber", "repository", "embedding", "embeddingModel", "modelVersion", "textHash", "textPreview", "dimensions", "indexedAt", "updatedAt", "sourceRevision")
       VALUES ($1, $2, $3, $4::vector, $5, $6, $7, $8, $9, NOW(), NOW(), $10)
       ON CONFLICT ("issueNumber", "repository", "embeddingModel", "modelVersion")
       DO UPDATE SET
         "embedding" = EXCLUDED."embedding",
         "textHash" = EXCLUDED."textHash",
         "textPreview" = EXCLUDED."textPreview",
         "updatedAt" = NOW(),
         "sourceRevision" = EXCLUDED."sourceRevision"`,
      doc.id,
      doc.issueNumber,
      doc.repository,
      embeddingArray,
      embeddingResult.model,
      embeddingResult.modelVersion,
      textHash,
      doc.text.slice(0, 200),
      embeddingResult.dimensions,
      doc.updatedAt,
    );
  }

  async remove(id: string): Promise<void> {
    // The id format is "repo#number" — parse to find the matching record
    const parsed = parseDocumentId(id);
    if (parsed) {
      await this.db.$executeRawUnsafe(
        `DELETE FROM issue_embeddings WHERE "issueNumber" = $1 AND "repository" = $2`,
        parsed.issueNumber,
        parsed.repository,
      );
    } else {
      // Fallback: try to match by id directly
      await this.db.$executeRawUnsafe(
        `DELETE FROM issue_embeddings WHERE "id" = $1`,
        id,
      );
    }
  }

  async search(query: string, topK: number): Promise<SemanticMatch[]> {
    const embeddingResult = await this.embeddingProvider.embed(query);
    const embeddingArray = `[${embeddingResult.embedding.join(",")}]`;

    const results = await this.db.$queryRawUnsafe<
      Array<{ issueNumber: number; similarity: number }>
    >(
      `SELECT "issueNumber", 1 - ("embedding" <=> $1::vector) as similarity
       FROM issue_embeddings
       WHERE "embeddingModel" = $2 AND "modelVersion" = $3
       ORDER BY "embedding" <=> $1::vector
       LIMIT $4`,
      embeddingArray,
      this.embeddingProvider.model,
      this.embeddingProvider.modelVersion,
      topK,
    );

    return results
      .filter((r) => r.similarity >= this.minSimilarity)
      .map((r) => ({
        issueNumber: r.issueNumber,
        similarity: r.similarity,
      }));
  }

  async health(): Promise<SemanticIndexHealth> {
    try {
      const countResult = await this.db.$queryRawUnsafe<Array<{ count: bigint }>>(
        `SELECT COUNT(*) as count FROM issue_embeddings WHERE "embeddingModel" = $1 AND "modelVersion" = $2`,
        this.embeddingProvider.model,
        this.embeddingProvider.modelVersion,
      );

      const documentCount = Number(countResult[0]?.count ?? 0);

      if (documentCount === 0) {
        return {
          status: "empty",
          documentCount: 0,
          detail: `pgvector index contains no embeddings for model ${this.embeddingProvider.model}@${this.embeddingProvider.modelVersion}. Run backfill to populate.`,
        };
      }

      // Check for stale embeddings (count all embeddings regardless of current model)
      const totalResult = await this.db.$queryRawUnsafe<Array<{ count: bigint }>>(
        `SELECT COUNT(*) as count FROM issue_embeddings`,
      );
      const totalCount = Number(totalResult[0]?.count ?? 0);
      const staleCount = totalCount - documentCount;

      if (staleCount > this.staleThreshold) {
        return {
          status: "operational",
          documentCount,
          detail: `pgvector index operational with ${documentCount} current embeddings. Warning: ${staleCount} stale embeddings from previous model versions need reindexing.`,
        };
      }

      return {
        status: "operational",
        documentCount,
        detail: `pgvector index operational with ${documentCount} embeddings (model: ${this.embeddingProvider.model}@${this.embeddingProvider.modelVersion}).`,
      };
    } catch (error) {
      // If the table doesn't exist or pgvector is not installed, report disabled
      const message = error instanceof Error ? error.message : String(error);
      if (
        message.includes("does not exist") ||
        message.includes("type \"vector\" does not exist") ||
        message.includes("extension") ||
        message.includes("ECONNREFUSED")
      ) {
        return {
          status: "disabled",
          documentCount: 0,
          detail: `pgvector unavailable: ${message.slice(0, 150)}. Semantic search disabled.`,
        };
      }
      return {
        status: "disabled",
        documentCount: 0,
        detail: `pgvector health check failed: ${message.slice(0, 150)}`,
      };
    }
  }

  /**
   * Retrieve freshness statistics for the index.
   */
  async getFreshness(): Promise<{
    totalEmbeddings: number;
    currentModelEmbeddings: number;
    staleEmbeddings: number;
    oldestEmbedding: Date | null;
    newestEmbedding: Date | null;
  }> {
    const stats = await this.db.$queryRawUnsafe<
      Array<{
        total: bigint;
        current: bigint;
        oldest: Date | null;
        newest: Date | null;
      }>
    >(
      `SELECT
         COUNT(*) as total,
         COUNT(*) FILTER (WHERE "embeddingModel" = $1 AND "modelVersion" = $2) as current,
         MIN("indexedAt") as oldest,
         MAX("indexedAt") as newest
       FROM issue_embeddings`,
      this.embeddingProvider.model,
      this.embeddingProvider.modelVersion,
    );

    const row = stats[0];
    const total = Number(row?.total ?? 0);
    const current = Number(row?.current ?? 0);

    return {
      totalEmbeddings: total,
      currentModelEmbeddings: current,
      staleEmbeddings: total - current,
      oldestEmbedding: row?.oldest ?? null,
      newestEmbedding: row?.newest ?? null,
    };
  }

  /**
   * Find embeddings that are stale (textHash doesn't match current issue text).
   */
  async findStaleEmbeddings(
    issues: Array<{ issueNumber: number; repository: string; currentTextHash: string }>,
  ): Promise<Array<{ issueNumber: number; repository: string }>> {
    if (issues.length === 0) return [];

    const stale: Array<{ issueNumber: number; repository: string }> = [];

    // Check in batches of 100
    for (let i = 0; i < issues.length; i += 100) {
      const batch = issues.slice(i, i + 100);
      const conditions = batch
        .map((_, idx) => `("issueNumber" = $${idx * 3 + 1} AND "repository" = $${idx * 3 + 2} AND "textHash" != $${idx * 3 + 3})`)
        .join(" OR ");

      const params = batch.flatMap((issue) => [
        issue.issueNumber,
        issue.repository,
        issue.currentTextHash,
      ]);

      const results = await this.db.$queryRawUnsafe<
        Array<{ issueNumber: number; repository: string }>
      >(
        `SELECT DISTINCT "issueNumber", "repository" FROM issue_embeddings WHERE ${conditions}`,
        ...params,
      );

      stale.push(...results);
    }

    return stale;
  }

  /**
   * Delete all embeddings for a specific model version (used during migration).
   */
  async deleteByModelVersion(model: string, version: string): Promise<number> {
    return this.db.$executeRawUnsafe(
      `DELETE FROM issue_embeddings WHERE "embeddingModel" = $1 AND "modelVersion" = $2`,
      model,
      version,
    );
  }
}

/**
 * Compute a stable hash of the issue text for revision tracking.
 */
export function computeTextHash(text: string): string {
  return createHash("sha256").update(text).digest("hex").slice(0, 16);
}

/**
 * Parse a document ID in the format "repo#number" back to its components.
 */
function parseDocumentId(id: string): { repository: string; issueNumber: number } | null {
  const hashIdx = id.lastIndexOf("#");
  if (hashIdx <= 0) return null;
  const repository = id.slice(0, hashIdx);
  const issueNumber = parseInt(id.slice(hashIdx + 1), 10);
  if (isNaN(issueNumber)) return null;
  return { repository, issueNumber };
}
